// Build cache from two sheet reads and write to file.
const fs = require('fs');
const path = require('path');

function normBool(v) {
  if (typeof v === 'boolean') return v;
  if (typeof v === 'string') return !/^false$/i.test(v.trim()) && v.trim() !== '';
  return Boolean(v);
}

function safeSplit(text) {
  if (text == null) return [];
  if (Array.isArray(text)) return text.map(String).map((s) => s.trim()).filter(Boolean);
  return String(text)
    .split(/\r?\n|\|\||,/)
    .map((s) => s.trim())
    .filter(Boolean);
}

function collectKeywords(rows) {
  const out = {};
  for (const row of rows) {
    const category = (row.Category || row.category || '').trim();
    if (!category) continue;
    if (!normBool(row.Active ?? true)) continue;
    const keyword = (row.Keyword || row.keyword || '').trim();
    if (!keyword) continue;
    if (!out[category]) out[category] = [];
    out[category].push(keyword);
  }
  return out;
}

function collectReplies(rows) {
  const out = {};
  for (const row of rows) {
    const category = (row.Category || row.category || '').trim();
    if (!category) continue;
    const locale = (row.Locale || row.locale || '').trim();
    const weightRaw = (row.Weight || row.weight || '').toString().trim();
    const weight = weightRaw ? Number(weightRaw) : undefined;
    const replies = safeSplit(row.Reply || row.reply || '');
    if (!replies.length) continue;
    if (!out[category]) out[category] = {};
    if (!out[category][locale]) out[category][locale] = [];
    for (const text of replies) {
      const entry = weight ? { text, weight } : { text };
      out[category][locale].push(entry);
    }
  }
  return out;
}

const keywordsRows = $items('Google Sheets Keywords', 0).map((i) => i.json);
const repliesRows = $items('Google Sheets Replies', 0).map((i) => i.json);

const pageId = $env.CONFIG_PAGE_ID || '102450935821483';
const cache = {
  meta: {
    updatedAt: new Date().toISOString(),
    source: 'sheet',
    sheetId: $env.CONFIG_SHEET_ID || 'not-set',
  },
  data: {
    pageOverrides: {
      [pageId]: {
        keywords: { th: collectKeywords(keywordsRows) },
        replies: collectReplies(repliesRows),
      },
    },
  },
};

const cachePath =
  $env.WORKFLOW3_CONFIG_CACHE_PATH ||
  path.join(process.cwd(), '.n8n-dev/config-cache/keywords.json');
fs.mkdirSync(path.dirname(cachePath), { recursive: true });
fs.writeFileSync(cachePath, JSON.stringify(cache, null, 2), 'utf8');

return [
  {
    json: {
      ok: true,
      cachePath,
      updatedAt: cache.meta.updatedAt,
      categories: Object.keys(cache.data.pageOverrides[pageId].replies || {}),
    },
  },
];
